// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, address user, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(minSum <= 1e30);
        depositAmount = bound(depositAmount, 1, 1e27);
        collectAmount = bound(collectAmount, 1, 1e27);
        c.SetMinSum(minSum);
        c.Initialized();
        vm.deal(user, depositAmount);
        vm.prank(user);
        (bool success,) = address(c).call{value: depositAmount}("");
        if (success) {
            vm.prank(user);
            c.Collect(collectAmount);
        }
        assertTrue(c.MinSum() == minSum);
    }
}

